WFJ.Data.add("gossip", {
  ["910245591a68f817"] = { "Un vero professionista conosce i propri limiti, e non mi vergogno di ammettere che le tue abilità superano le mie. Voglio che tu vada a trovare Kitta Firewind alla ⟦Tower of Azora=Torre di Azora⟧. È molto rinomata, e a ragione.", "." },
  ["9102a99eb893b769"] = { "Sì, lo sono.", "." },
  ["910373bfc47cc26e"] = { "Sì, certo.", "." },
  ["9116dbea17ce2ecf"] = { "Tyrande manda le sue preghiere. Madre Luna benedice tutti noi.", "." },
  ["9120adca5a6dff84"] = { "Voglio vedere la tua merce.", "." },
  ["9122a1986474ce48"] = { "Quasi fatto! Ancora un pochino!", "." },
  ["9126238580c671ee"] = { "Malygos, eh?", "." },
  ["91282d286ea2ebd0"] = { "Non cercare oltre: c'è la Locanda del Fiero Leone di ⟦Goldshire=Borgodoro⟧. Con un'ampia scelta di birre e morbidi letti di piuma, non potresti chiedere un posto migliore per riposare.", "." },
  ["912a719f887eef47"] = { "Non vedi che ho da fare qui? Va' a nord lungo la strada per Orgrimmar e chiedi a uno dei grunt. Non puoi sbagliare.", "." },
  ["912c2e977f0c49aa"] = { "Va' al ⟦Freewind Post=Presidio di Ventolibero⟧, a ⟦Thousand Needles=Millepicchi⟧, e troverai l'anziano Skyseer.", "." },
  ["912d46b4f63c4b7c"] = { "Agenti del ⟦Cenarion Circle=Circolo Cenariano⟧ hanno scoperto informazioni inquietanti riguardo alla situazione attuale a Eldre'Thalas. Non so che decisione prendere al riguardo, e senza dubbio cercherò presto l'aiuto di persone abili, capaci di cavarsela in combattimento.\n\nPer agire come si deve a Eldre'Thalas, però, bisogna conoscere la tradizione di un oggetto noto come Fruit of Fertility.", "." },
  ["9136476f3df99279"] = { "Un altro cade!", "." },
  ["913bb3a1c1283b82"] = { "<TRADITORE/TRADITRICE>!", "." },
  ["913ee26b17ca340a"] = { "Salve, Frankal. Ho sentito che potresti sapere qualcosa su dove si trovi la signora Natalia Mar'alith.", "." },
  ["91425f89a9bc82f2"] = { "{name}, giusto? Gran bel lavoro quello che hai lì. Ti prendo con me, e t'insegnerò a fare armature degne di re Magni in persona.", "." },
  ["9144cf0c8a0f649e"] = { "Armand Cromwell sempre su molo in ⟦Magic Quarter=Quartiere della Magia⟧. Pesce in melma verde ha sapore extra buono. Tu prova.", "." },
  ["91488e073c4a474e"] = { "Maywiki, uno gnomo meschino è scappato con la mia ⟦Zandalar Augur's Belt=Cintura del Profeta degli Zandalari⟧. Puoi darmene una nuova?", "." },
  ["914b7adbc2d06f01"] = { "Il Northern Pylon accetta cristalli gialli, rossi e verdi.\n\nLa focalizzazione è l'energia che si può creare usando i cristalli gialli come principale fonte di potere. Ci sono due effetti possibili: uno che infligge danni e uno che annulla i danni.\n\nCarica del Cristallo richiede cristalli rossi e gialli. Produce una grande esplosione che stordisce i nemici.\n\nGuarigione del Cristallo richiede cristalli gialli e verdi. Ti fornisce un'aura curativa.", "." },
  ["914d540182f5d007"] = { "Dalla nostra fattoria al tuo piatto: è la genuina bontà della Masseria Buongusto!", "." },
  ["91531bb84ebf1840"] = { "Combattete fino all'ultimo respiro, fratelli e sorelle!", "." },
  ["915320a733b71b20"] = { "Oh sì. Noi ha {name} proprio qui.", "." },
  ["9156f376b1a4ea22"] = { "La tua insolenza è sconcertante, idiota! Divorerò la tua anima!", "." },
  ["915a24da15243540"] = { "Lascia che ti aiuti con quelli.", "." },
  ["916dd3f774f6090c"] = { "Ti presento il ⟦Libram of Tenacity=Compendio sulla Tenacia⟧.", "." },
  ["91719c8e0ce5cd81"] = { "Grazie, {name}! Troverai Keras Wolfheart sulla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧, vicino agli istruttori. Ti guiderà fino al ⟦Arathi Basin=Bacino d'Arathi⟧. Buona fortuna, e grande onore a te.", "." },
  ["9173a1f0c2d936d7"] = { "Jin'rokh, temo di aver perso il mio ⟦Zandalar Freethinker's Breastplate=Pettorale Corazzato del Libero Pensatore degli Zandalari⟧. Puoi darmene uno nuovo?", "." },
  ["9173f49245549da1"] = { "Ti diamo il benvenuto nella nostra casa, {name}. Radnaal e io abbiamo poco da offrire, ma quel poco di ospitalità che possiamo darti è tuo.", "." },
  ["917672e029ca241c"] = { "Posso insegnarti le tecniche di ⟦First Aid=Primo Soccorso⟧.", "." },
  ["917aa53022b30801"] = { "Il Flagello ha fatto irruzione nel Bastione! Raddoppiate gli sforzi! Non dobbiamo fallire!", "." },
  ["917be35a5afc1eb5"] = { "Invasori dall'entroterra! Fuoco!", "." },
  ["918fbe57e7f3c6d7"] = { "Hanno detto che non ho cervello, ma glielo farò vedere io. Sorveglierò ogni pentola che ho e dimostrerò che bollono comunque. Sì, sono inarrestabile! Chi è senza cervello adesso, eh? Eh!?", "." },
  ["919374d1b71f4f28"] = { "La ⟦Syndicate=Lega dei Tagliagole⟧ tiene molte casse chiuse di rifornimenti nel ⟦Durnholde Keep=Forte Durnholde⟧, a ⟦Hillsbrad=Colletorto⟧.", "." },
  ["9198e191bd8d7151"] = { "Ah, eccone uno.", "." },
  ["919bff9afffae312"] = { "Va' a sederti vicino al fuoco e possiamo cominciare.", "." },
  ["91ac8c7ed704ecfe"] = { "Trovi una cassetta postale proprio laggiù, vicino alla Stonefire Tavern. È appena a nord dei cancelli di ⟦Ironforge=Forgiardente⟧.", "." },
  ["91af32bc65d73286"] = { "%s si nasconde tra i cespugli.", "." },
  ["91b3a773faf0c72e"] = { "IN RIGA, VERMI!", "." },
  ["91b4ee9c343ba23b"] = { "Voi pezzi di ricambio! Noi fa più Flagello in necropoli.", "." },
  ["91bf79f4b38360e6"] = { "{name}! Ho finito!", "." },
  ["91c4bdbfd82e8c5b"] = { "Oh beh, di sicuro si farà vedere più tardi.", "." },
  ["91ca8c3ced1415d1"] = { "Ve la faremo vedere noi...", "." },
  ["91d09e68e4e45b05"] = { "Dai, Fluffy! Voglio solo farti il bagno!", "." },
  ["91d4d3a2bd2acf58"] = { "L'unico posto di ⟦Stormwind=Roccavento⟧ dove magia e spiriti si mescolano: vieni al Blue Recluse!", "." },
  ["91d6548a299bf42f"] = { "<Benvenuto/Benvenuta> a ⟦Stormwind=Roccavento⟧. Ci è voluto molto per ricostruirla, ma ne è valsa la pena. Allora, sei qui in visita o per affari?", "." },
  ["91db2e742fc6b5a1"] = { "Come osi provare a zergarmi, mezza calzetta!", "." },
  ["91e1e326884eb73d"] = { "È tutto raccolto, {class}. Tutto viene trasportato a ⟦Silithus=Silitus⟧ per i preparativi finali e dovrebbe arrivare entro $2113w giorni. Tutte le nostre forze riunite attendono l'<eroe/eroina> che completerà la riunificazione dello Scettro delle Sabbie Mutevoli, suonerà il gong e darà inizio alla Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧.", "." },
  ["91f15550fae25581"] = { "Non siete che vermi sotto i miei piedi. Osate sfidarmi?", "." },
  ["91f18130985c6c3f"] = { "Bentornat<o/a>, {class}. Vedo che il ciottolo è stato molto usato. Molti dei nostri nemici sono caduti davanti alle tue abilità ultraterrene. Le loro sofferenze sono state grandi. È ora che io potenzi il ciottolo. Dammelo.", "." },
  ["91f35c6b3f5ba370"] = { "Custodisco il ricettacolo della sua rinascita. Se intendi affrontare questo compito, dovrai fortificare il ricettacolo e infine spezzare il dominio di Ragnaros in persona!", "." },
  ["91f7f3fd5ff4d547"] = { "Su, facciamo a pugni, come gente civile.", "." },
  ["91febcc232d00b42"] = { "Brutto piccolo...!", "." },
})
